/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=set()
for page in r.pages:
    for annot in page.get('/Annots',[]):
        a=annot.get_object().get('/A')
        if a:
            a=a.get_object()
            if a.get('/URI'):
                links.add(str(a['/URI']))
print('\\n'.join(sorted(links)))
PY"
